--!strict
-- TerritoryService.lua — Phase 6: zone capture + territory bonuses.
-- SERVER-AUTHORITATIVE: influence accrual, capture and bonus math all live here;
-- clients only receive TERRITORY_SYNC snapshots. Zone coordinates come from
-- WorldLayout (generated by build_place.py). Zone state (ownership + influence
-- pools) persists in a dedicated DataStore, cache-first with a graceful
-- fallback so the slice still runs before the place is published.

local Players = game:GetService("Players")
local DataStoreService = game:GetService("DataStoreService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerScriptService = game:GetService("ServerScriptService")

local Net = require(ReplicatedStorage.Net)
local Signal = require(ReplicatedStorage.Shared.Util.Signal)
local TerritoryConfig = require(ReplicatedStorage.Shared.Configs.TerritoryConfig)
local WorldLayout = require(ReplicatedStorage.Shared.WorldLayout)
local DataService = require(ServerScriptService.Services.DataService)
local ClanService = require(ServerScriptService.Services.ClanService)
local CampaignService = require(ServerScriptService.Services.CampaignService)

local cfg = TerritoryConfig

local TerritoryService = {}
TerritoryService.Events = {
	ZoneCaptured = Signal.new(), -- (player, zoneKey) — contributing member credit
}

local zones: { [string]: any } = {} -- key -> { Owner: number?, Influence: { [number]: number } }
local dirty: { [string]: boolean } = {}
local store = nil
local zoneDefs = WorldLayout.TERRITORY_ZONES or {}
local banners: { [string]: BasePart } = {}

-- ---------------------------------------------------------------- store ----
local function persistDirty()
	if not store then
		return
	end
	local snap: { [string]: any } = {}
	for key, zone in pairs(zones) do
		local influence: { [number]: number } = {}
		for clanId, v in pairs(zone.Influence) do
			influence[clanId] = v
		end
		snap[key] = { Owner = zone.Owner, Influence = influence }
	end
	for key in pairs(dirty) do
		dirty[key] = nil
	end
	task.spawn(function()
		local ok, err = pcall(function()
			store:SetAsync("ZONE_INDEX", snap)
		end)
		if not ok then
			warn("[TerritoryService] save failed: " .. tostring(err))
			for key in pairs(snap) do
				dirty[key] = true
			end
		end
	end)
end

-- -------------------------------------------------------------- helpers ----
local function playerClanId(player: Player): number?
	local data = DataService.get(player)
	return data and data.Clan and data.Clan.Id or nil
end

local function insideZone(player: Player, def): boolean
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root or not root:IsA("BasePart") then
		return false
	end
	local p = root.Position
	local dx, dz = p.X - def.x, p.Z - def.z
	return (dx * dx + dz * dz) <= def.radius * def.radius
end

local function areAllied(a: number?, b: number?): boolean
	if not a or not b then
		return false
	end
	local allies = ClanService.allyIdsOf(a)
	return allies and table.find(allies, b) ~= nil
end

local function clanMembersOnline(clanId: number?): { Player }
	local out = {}
	local data_ids = clanId and ClanService.memberUserIdsOf(clanId) or nil
	if not data_ids then
		return out
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if table.find(data_ids, p.UserId) then
			table.insert(out, p)
		end
	end
	return out
end

local function tintBanner(key: string, clanId: number?)
	local banner = banners[key]
	if not banner then
		return
	end
	-- founder-derived tint: rotate a palette keyed by clan id so clans read apart
	local palette = {
		{ 228, 120, 66 }, { 90, 150, 235 }, { 110, 200, 110 }, { 225, 190, 70 },
		{ 175, 110, 220 }, { 90, 210, 210 }, { 235, 120, 150 }, { 150, 140, 230 },
	}
	local c = clanId and palette[1 + (clanId % 8)] or nil
	banner.Color = c and Color3.fromRGB(c[1], c[2], c[3]) or Color3.fromRGB(200, 200, 200)
end

-- ----------------------------------------------------------------- sync ----
function TerritoryService.sync(player: Player, open: boolean?)
	local list = {}
	for _, def in pairs(zoneDefs) do
		local zone = zones[def.key] or { Owner = nil, Influence = {} }
		local tag = nil
		if zone.Owner then
			tag = ClanService.tagOf(zone.Owner) or "?" .. tostring(zone.Owner)
		end
		table.insert(list, {
			Key = def.key,
			Name = def.name,
			Owner = zone.Owner,
			OwnerTag = tag,
			Radius = def.radius,
			X = def.x,
			Z = def.z,
		})
	end
	table.sort(list, function(a, b)
		return a.Key < b.Key
	end)
	Net.event("TERRITORY_SYNC"):FireClient(player, {
		Open = open or nil,
		Zones = list,
	})
end

local function broadcastSync()
	for _, p in ipairs(Players:GetPlayers()) do
		TerritoryService.sync(p)
	end
end

-- ----------------------------------------------------------------- loop ----
local function influenceTick()
	for _, def in pairs(zoneDefs) do
		local zone = zones[def.key]
		if not zone then
			continue
		end
		local changed = false
		local present: { [number]: number } = {} -- clanId -> members present
		for _, player in ipairs(Players:GetPlayers()) do
			local clanId = playerClanId(player)
			if clanId and insideZone(player, def) then
				present[clanId] = (present[clanId] or 0) + 1
			end
		end

		for clanId, n in pairs(present) do
			local rate = cfg.TICK_RATE * n
			local owner = zone.Owner
			if owner and owner ~= clanId and (present[owner] or 0) > 0 and not areAllied(clanId, owner) then
				rate = math.floor(rate * cfg.DEFENDED_RATE_MULT + 0.5)
			end
			if owner and areAllied(clanId, owner) then
				rate = math.floor(rate * cfg.ALLIED_RATE_MULT + 0.5)
			end
			zone.Influence[clanId] = (zone.Influence[clanId] or 0) + rate
			changed = true
		end
		for clanId, v in pairs(zone.Influence) do
			if not present[clanId] then
				local drained = v - cfg.DECAY_PER_TICK
				if drained > 0 then
					zone.Influence[clanId] = drained
				else
					zone.Influence[clanId] = nil
				end
			end
		end

		-- capture: highest pool crossing the threshold takes the zone
		local best, bestN = nil, 0
		for clanId, v in pairs(zone.Influence) do
			if v > bestN then
				best, bestN = clanId, v
			end
		end
		if best and bestN >= cfg.CAPTURE_INFLUENCE and best ~= zone.Owner then
			zone.Owner = best
			zone.Influence = {}
			dirty[def.key] = true
			tintBanner(def.key, best)
			local credit = clanMembersOnline(best)[1]
			if credit then
				TerritoryService.Events.ZoneCaptured:Fire(credit, def.key)
			end
			local tag = ClanService.tagOf(best) or ("clan#" .. tostring(best))
			for _, p in ipairs(clanMembersOnline(best)) do
				Net.event("TOAST"):FireClient(p, { text = ("%s CAPTURED — banner %s is yours"):format(def.name, tag), duration = 5 })
			end
			CampaignService.announce(("%s: BANNER RAISED BY CLAN %s"):format(string.upper(def.name), tag))
			broadcastSync()
		end
		if changed then
			dirty[def.key] = true
		end
	end
end

-- --------------------------------------------------------------- bonus ----
local function bonusLevelFor(player: Player, zoneKey: string): number
	-- 0 none | 1 owner | 2 ally-of-owner
	local clanId = playerClanId(player)
	if not clanId then
		return 0
	end
	local zone = zones[zoneKey]
	if not zone or not zone.Owner then
		return 0
	end
	if zone.Owner == clanId then
		return 1
	end
	return areAllied(clanId, zone.Owner) and 2 or 0
end

function TerritoryService.contractCashMult(player: Player): number
	local level = bonusLevelFor(player, "PLAZA")
	local mult = cfg.ZONE_BONUS.PLAZA.Mult
	if level == 1 then
		return mult
	elseif level == 2 then
		return 1 + (mult - 1) / 2
	end
	return 1.0
end

function TerritoryService.pickupCashFlat(player: Player): number
	local level = bonusLevelFor(player, "DEPOT")
	local flat = cfg.ZONE_BONUS.DEPOT.Flat
	if level == 1 then
		return flat
	elseif level == 2 then
		return math.floor(flat / 2)
	end
	return 0
end

function TerritoryService.settlementYieldFlat(player: Player): number
	local level = bonusLevelFor(player, "YARD")
	local flat = cfg.ZONE_BONUS.YARD.Flat
	if level == 1 then
		return flat
	elseif level == 2 then
		return math.floor(flat / 2)
	end
	return 0
end

-- ----------------------------------------------------------------- init ----
function TerritoryService.Init()
	-- load zone state (graceful when unpublished — DataStore API off)
	pcall(function()
		store = DataStoreService:GetDataStore("DistrictsAfterlight_Territory_v1")
		local ok, data = pcall(function()
			return store:GetAsync("ZONE_INDEX")
		end)
		if ok and type(data) == "table" then
			for key, entry in pairs(data) do
				if zoneDefs[key] then
					zones[key] = { Owner = entry.Owner, Influence = entry.Influence or {} }
				end
			end
		end
	end)
	for _, def in pairs(zoneDefs) do
		zones[def.key] = zones[def.key] or { Owner = nil, Influence = {} }
	end

	-- banners: tint by current owner once the world part exists
	task.spawn(function()
		local meridian = workspace:WaitForChild("Meridian", 20)
		local flags = meridian and meridian:WaitForChild("TerritoryFlags", 20)
		if flags then
			for key in pairs(zoneDefs) do
				local banner = flags:FindFirstChild("TerritoryBanner_" .. key, true)
				if banner and banner:IsA("BasePart") then
					banners[key] = banner
					tintBanner(key, zones[key].Owner)
				end
			end
		end
	end)

	-- clan dissolution can orphan a zone — free it
	ClanService.Events.ClanDissolved:Connect(function(clanId)
		for _, def in pairs(zoneDefs) do
			local zone = zones[def.key]
			if zone and zone.Owner == clanId then
				zone.Owner = nil
				dirty[def.key] = true
				tintBanner(def.key, nil)
			end
		end
		broadcastSync()
	end)

	-- presence loop
	task.spawn(function()
		while true do
			task.wait(cfg.TICK)
			influenceTick()
		end
	end)

	-- periodic flush
	task.spawn(function()
		while true do
			task.wait(60)
			persistDirty()
		end
	end)

	game:BindToClose(function()
		persistDirty()
		task.wait(2)
	end)

	-- late-hook bonus providers (services above stay require-cycle free)
	local ContractService = require(script.Parent.ContractService)
	ContractService.PickupBonus = TerritoryService.pickupCashFlat
	ContractService.DeliverCashMult = TerritoryService.contractCashMult
	local SettlementService = require(script.Parent.SettlementService)
	SettlementService.YieldBonus = TerritoryService.settlementYieldFlat

	Players.PlayerAdded:Connect(function(player)
		TerritoryService.sync(player)
	end)
	for _, p in ipairs(Players:GetPlayers()) do
		TerritoryService.sync(p)
	end
end

return TerritoryService